                const { task } = await buildTask({
                    type: 'collect',
                    workerKind,
                    entryInfo,
                    index,
                    context,
                    project,
                    runtimeConfig,
                    deletedEnvKeys,
                    color,
                    setupEntries,
                    setupAssets,
                    assetNames,
                    updateSnapshot,
                    getAssetFiles,
                    getSourceMaps,
                    rpcMethods,
